// Original practice questions written for syllabus v1.6b (Intermediate).
// Format: Q(syllabusCode, question, [CORRECT, wrong, wrong, wrong], explanation, memoryHook?)
// The correct answer is always listed first here; the app shuffles the options.
window.QUESTIONS = [];
function Q(code, q, opts, x, hook) {
  const n = window.QUESTIONS.filter(e => e.code === code).length + 1;
  window.QUESTIONS.push({ id: code + "-" + n, code, sec: +code[0], q, opts, x, hook: hook || "" });
}

/* ───────────── SECTION 1 · LICENSING ───────────── */
Q("1A1", "Your UK Intermediate licence allows you to transmit from", ["the UK, Channel Islands and Isle of Man, including territorial seas", "anywhere in Europe under CEPT", "any ship at sea, whatever its flag", "the UK mainland only"], "The licence covers the UK, Channel Islands and Isle of Man and their territorial seas, plus UK-registered ships and aircraft. Other countries do not routinely recognise the Intermediate licence.");
Q("1A1", "You are a passenger on a ship registered in another country, out at sea. Your Intermediate licence", ["does not let you transmit on the amateur bands", "lets you use 2m and 70cm only", "lets you use all UK amateur bands", "lets you transmit at reduced power only"], "The licence only extends to UK-registered vessels. On a foreign-registered ship you have no permission to transmit at all.", "Foreign flag = no TX.");
Q("1A2", "Which Regional Secondary Locator (RSL) shows a station operating in Wales?", ["W", "C", "S", "M"], "RSLs: D Isle of Man, E England, I Northern Ireland, J Jersey, M Scotland, U Guernsey, W Wales.", "D-E-I-J-M-U-W: 'Did Every Irish Jockey Meet Us in Wales?'");
Q("1A2", "Which RSL is used in Scotland?", ["M", "S", "G", "C"], "M is Scotland (think 'MacScotland'). GM, MM, 2M are Scottish calls.");
Q("1A2", "For a 2E-series Intermediate callsign, use of the Regional Secondary Locator is", ["mandatory", "optional at all times", "only needed on HF", "only needed outside England"], "Since the 2024 licence changes, RSLs are optional for most callsigns but remain mandatory for the 2x-series callsigns.");
Q("1A3", "If you move house you must", ["tell Ofcom of the new address straight away", "wait until your five-year revalidation", "tell the RSGB, who inform Ofcom", "do nothing unless you operate mobile"], "Changes of name or address must be notified to Ofcom immediately. Failing to do so can lead to revocation.");
Q("1A3", "How often must you confirm your licence details with Ofcom?", ["At least every five years", "Every year", "Every ten years", "Only when asked"], "Licence details must be revalidated at least every five years, or the licence can be revoked.");
Q("1A4", "You must give your callsign when you", ["change frequency or mode", "turn the receiver volume up", "move the antenna", "switch on the transceiver"], "Identify at the start and end of contacts and whenever you change frequency, mode, digital protocol, supervisor or RSL.");
Q("1B1", "An Intermediate licensee visits a Full licensee and transmits at 200 W using the Full licensee's station. The Intermediate must", ["use the Full licensee's callsign and be directly supervised by them", "use their own callsign without supervision", "use their own callsign under supervision", "not transmit, as this is illegal"], "Above your own 100 W limit you are operating under the Full licensee's licence, so it is their callsign and they must be directly supervising.", "Their power → their call → their supervision.");
Q("1B1", "You hold 2E0ABC. Your friend GW4XYZ, a Full licensee from Wales, supervises you at your home in England at 400 W. Which callsign is used?", ["G4XYZ", "2E0ABC", "GW4XYZ", "2W0ABC"], "You use the supervisor's callsign, with the RSL for where the station actually is. You're in England, so the Welsh W is dropped: G4XYZ.");
Q("1B1", "With permission, you use another amateur's radio without supervision, within your own licence limits. You use", ["your own callsign and your own licence conditions", "the owner's callsign", "the owner's callsign with /P", "either callsign"], "Unsupervised and within your own privileges, it becomes your 'Radio Equipment' and you identify with your own call.");
Q("1C1", "Amateur messages may normally be sent to", ["other amateur stations only", "anyone listening", "broadcast listeners in an emergency", "any licensed radio user"], "Messages go to other amateurs only. General broadcasts are not allowed (a CQ call is fine). Content must not cause offence.");
Q("1C2", "Which of these is a User Service under the licence?", ["The Coastguard", "The RSPCA", "A security firm", "A breakdown recovery company"], "User Services are the Category 1 and 2 responders: Police, Fire, Ambulance, Coastguard, plus local authorities.");
Q("1C2", "A member of a User Service may", ["use your Radio Equipment to send messages", "permit you to go out of band", "close your station down", "let you use encryption for personal messages"], "The licence lets a User Service member use your equipment to pass messages, and you can pass messages on their behalf.");
Q("1C2", "Encrypted transmissions are permitted", ["at the request of a User Service, or to control an amateur satellite", "whenever the message is private", "on frequencies above 30 MHz", "never in any circumstances"], "Encryption is banned except for messages at a User Service's request, or for satellite control.");
Q("1D1", "Who can require you to reduce emissions that are causing undue interference?", ["A person authorised by Ofcom", "The neighbour suffering interference", "A police officer", "Your local council"], "Only Ofcom (or someone it authorises) has that power. They can also require modification or closedown.");
Q("1D1", "Your licence requires that your station must NOT cause", ["undue interference to other radio users", "any interference to any electrical equipment", "interference to other amateurs only", "audible noise late at night"], "The key word is 'undue' and it's about other radio users.", "Watch for 'any' vs 'undue' in the answers.");
Q("1D2", "When must you keep a log?", ["When Ofcom requires you to, for a specified period", "Always, for every contact", "Only when operating portable", "Only during contests"], "Logs are no longer routinely mandatory, but Ofcom can direct you to keep one.");
Q("1E1", "A radio link used to control your transceiver remotely must be", ["adequately secure to prevent unauthorised use", "freely available to other amateurs", "on the 30 m band", "encrypted with a strong cipher"], "The control link must be secure, able to terminate transmissions promptly, and if on amateur frequencies, above 30 MHz and not encrypted.");
Q("1E1", "If an amateur frequency is used for a remote-control link it must be", ["above 30 MHz and not encrypted", "below 30 MHz and encrypted", "on 10.1 MHz only", "at least 100 W"], "Amateur-band control links: above 30 MHz, unencrypted (amateur traffic can't be encrypted).");
Q("1E1", "An unattended transceiver at a place other than your licensed address must have displayed next to it", ["your licence number", "your name and address", "a 'do not touch' warning", "your callsign only"], "The licence number must be displayed beside remotely operated equipment away from the main address.");
Q("1G1", "Above which levels must a full EMF compliance assessment be carried out?", ["10 W EIRP average or 100 W EIRP peak", "5 W ERP average or 50 W ERP peak", "10 W ERP average or 100 W ERP peak", "50 W EIRP average"], "If your station can exceed 10 W EIRP average or 100 W EIRP peak, you need a full assessment and must keep records.", "10 and 100, both EIRP.");
Q("1G1", "Your EIRP is 8 W average and 120 W peak. In terms of the EMF limits", ["the average is below the threshold but the peak is above", "both are below", "both are above", "the average is above but the peak is below"], "Average threshold 10 W EIRP (8 W is below). Peak threshold 100 W EIRP (120 W is above), so a full assessment is needed.");
Q("1G1", "You must repeat your EMF assessment when", ["you replace the antenna with a different type", "you renew your licence", "you rearrange the shack", "you disconnect the transmitter"], "Anything that changes the radiated field pattern or power (new antenna type, more power, new location) needs reassessment.");
Q("1G1", "The EMF restrictions in the licence are based on guidelines from", ["ICNIRP", "the IARU", "the ITU", "the RSGB"], "ICNIRP is the International Commission on Non-Ionizing Radiation Protection. The limits protect the general public.");
Q("1H1", "Using the EX308 schedule: which band has secondary status for Intermediates?", ["10.100–10.150 MHz", "14.000–14.250 MHz", "21.000–21.450 MHz", "28.0–29.7 MHz"], "30 m (10.1 MHz) is secondary. Most other HF bands are primary. Practise finding this in the booklet fast.");
Q("1H1", "Which band has its power limit given as ERP rather than PEP?", ["135.7–137.8 kHz", "1.810–1.830 MHz", "10.100–10.150 MHz", "144–146 MHz"], "136 kHz is limited to 1 W ERP. 430–432 MHz is also ERP-limited (40 W ERP).");
Q("1H1", "On which frequency must amateurs accept interference from ISM users?", ["2.420 GHz", "1.860 MHz", "145.500 MHz", "432.100 MHz"], "ISM bands in the schedule include 2400–2450 MHz, 5755–5850 MHz and 24 GHz.");
Q("1H1", "The 431–432 MHz segment may not be used", ["within 100 km of Charing Cross, London", "in Scotland", "at more than 10 W", "for FM"], "That restriction is printed in Schedule 1. You have it in the exam, so just know where to look.");
Q("1H1", "What is the Intermediate power limit on 1.850–2.000 MHz?", ["32 W (15 dBW)", "100 W (20 dBW)", "10 W (10 dBW)", "1 W ERP"], "The top of 160 m is secondary with a 32 W limit. Almost everything else is 100 W.");
Q("1H1", "The maximum power from an airborne station on most allocated bands is", ["500 mW EIRP", "100 W PEP", "10 W ERP", "Not permitted at all"], "The schedule shows 500 mW EIRP for airborne operation on many bands.");

/* ───────────── SECTION 2 · TECHNICAL ───────────── */
Q("2A1", "A resistor marked 100 Ω measures 97 Ω. This is because", ["components are made within a tolerance", "the meter is faulty", "resistance changes with voltage", "it has been overheated"], "All components have a tolerance (e.g. ±5%, ±10%), so measured values differ slightly from marked values.");
Q("2C1", "What current flows when 12 V is applied across 4 kΩ?", ["3 mA", "48 mA", "3 A", "0.33 mA"], "I = V ÷ R = 12 ÷ 4000 = 0.003 A = 3 mA.", "Volts over kilohms gives milliamps.");
Q("2C1", "Two 1 kΩ resistors are connected in parallel. The combined resistance is", ["500 Ω", "2 kΩ", "1 kΩ", "250 Ω"], "Two equal resistors in parallel = half of one.", "Equal pair in parallel → halve it.");
Q("2C1", "A 2 kΩ and a 3 kΩ resistor are in series with a 10 V supply. The current is", ["2 mA", "5 mA", "0.5 mA", "20 mA"], "Series: add them = 5 kΩ. I = 10 ÷ 5 kΩ = 2 mA.");
Q("2C1", "The combined resistance of resistors in parallel is always", ["less than the smallest resistor", "more than the largest", "the average of them", "equal to the largest"], "Each extra parallel path lets more current through, so the total is below the smallest one. A handy check on calculations.");
Q("2C1", "R1 = 200 Ω and R2 = 600 Ω in series. 4 V is measured across R1. What is the supply voltage?", ["16 V", "12 V", "8 V", "4 V"], "Current = 4 ÷ 200 = 20 mA. Total R = 800 Ω, so V = 0.02 × 800 = 16 V. Or: R2 is 3× R1 so drops 12 V; 4 + 12 = 16.");
Q("2C2", "A potential divider has 10 kΩ on top and 10 kΩ below, across 12 V. The output is", ["6 V", "12 V", "3 V", "4 V"], "Equal resistors split the voltage equally: 6 V.");
Q("2C2", "A 12 V supply feeds three equal resistors in series. The voltage across two of them is", ["8 V", "4 V", "6 V", "12 V"], "Each takes 4 V. Two of them = 8 V.");
Q("2C3", "A battery's terminal voltage falls when current is drawn because of its", ["internal resistance", "PN junctions", "heating effect", "meter probe resistance"], "EMF is the 'open circuit' voltage. Current through the internal (source) resistance drops volts inside the battery, so the terminal PD falls.", "EMF = no load. PD = what you get under load.");
Q("2C3", "A supply gives 13.2 V at 1 A and 12.4 V at 5 A. Its open-circuit voltage is", ["13.4 V", "13.6 V", "13.2 V", "13.8 V"], "0.8 V lost for an extra 4 A, so source resistance is 0.2 Ω. At 1 A it drops 0.2 V, so open circuit = 13.2 + 0.2 = 13.4 V.");
Q("2D1", "A capacitor consists of", ["two conducting plates separated by an insulator", "a coil of wire", "a coil with a ferrite core", "a PN junction"], "Plates + dielectric (insulator). It stores charge in an electric field. Measured in farads.");
Q("2D1", "Capacitance increases if", ["the plate area is increased", "the plates are moved further apart", "the plate area is reduced", "air replaces the dielectric"], "Bigger plates, closer together, better dielectric = more capacitance.", "Big & close.");
Q("2D2", "A 6 µF and a 4 µF capacitor are in parallel. Total capacitance is", ["10 µF", "2.4 µF", "1.5 µF", "24 µF"], "Capacitors in parallel simply add (opposite to resistors).", "Capacitors are backwards: parallel adds.");
Q("2D2", "Two 10 µF capacitors in series give", ["5 µF", "20 µF", "10 µF", "100 µF"], "Series capacitors combine like parallel resistors: two equal → half.");
Q("2D3", "An electrolytic capacitor must be connected", ["the correct way round", "either way round", "only across AC", "with a series resistor"], "It's polarised. Reversed, it can overheat, vent or explode.");
Q("2D4", "An inductor stores energy in", ["its magnetic field", "its electric field", "its dielectric", "chemical form"], "Current in a coil creates a magnetic field, which stores energy. Capacitors store it in an electric field.");
Q("2D4", "A voltage is induced across a conductor when", ["it moves relative to a magnetic field", "it is heated", "it is in an electric field", "current is constant"], "Relative movement between a conductor and a magnetic field induces a voltage. This is the basis of generators and transformers.");
Q("2D5", "Three 6 mH inductors in series (no coupling) give", ["18 mH", "2 mH", "6 mH", "12 mH"], "Inductors combine like resistors: series adds.", "Inductors behave like resistors; capacitors are the odd ones out.");
Q("2D5", "Two 10 mH inductors in parallel (no coupling) give", ["5 mH", "20 mH", "10 mH", "100 mH"], "Like resistors: equal pair in parallel halves.");
Q("2D6", "A coil's inductance can be increased by", ["adding more turns", "reducing the number of turns", "spacing the turns further apart", "reducing the coil diameter"], "More turns, bigger diameter, closer spacing and a high-permeability core all increase inductance. Slug tuning moves a core in or out.");
Q("2E1", "A capacitor will", ["pass AC but block DC", "pass DC but block AC", "block both", "pass both equally"], "It charges and discharges each half cycle, so AC 'gets through', but DC stops once it's charged.");
Q("2E2", "The period of a 200 Hz signal is", ["5 ms", "50 ms", "20 ms", "200 ms"], "T = 1 ÷ f = 1 ÷ 200 = 0.005 s = 5 ms.");
Q("2E2", "A signal has a period of 1 µs. Its frequency is", ["1 MHz", "1 kHz", "1 Hz", "100 kHz"], "f = 1 ÷ T. Micro and mega cancel: 1 µs ↔ 1 MHz.", "ms ↔ kHz, µs ↔ MHz.");
Q("2E2", "Phase difference between two waves is expressed in", ["degrees", "hertz", "seconds", "volts"], "One full cycle = 360°.");
Q("2E3", "The RMS value of a 10 V peak sine wave is about", ["7.07 V", "14.1 V", "5 V", "10 V"], "Vrms = 0.707 × Vpeak.");
Q("2E3", "Which gives most heating in a 50 Ω resistor?", ["10 V DC", "12 V peak AC", "9 V RMS AC", "20 V peak-to-peak AC"], "Convert all to RMS: 10, 8.5, 9, 7.07. DC 10 V wins. RMS is the DC-equivalent heating value.");
Q("2E3", "RMS voltage is defined as", ["the DC voltage that gives the same heating", "the peak voltage", "the average voltage over a cycle", "half the peak-to-peak voltage"], "RMS = 'heating equivalent'.");
Q("2E4", "As frequency increases, a capacitor's reactance", ["decreases", "increases", "stays the same", "becomes zero at once"], "Capacitors pass high frequencies more easily.", "Capacitor: Climbing frequency → Collapsing reactance.");
Q("2E4", "Capacitive reactance is measured in ohms because it is", ["the ratio of RMS voltage to RMS current", "a form of heat loss", "the same as resistance", "the ratio of current to heat"], "Any V ÷ I ratio is in ohms. Reactance stores energy rather than turning it into heat.");
Q("2E5", "As frequency increases, an inductor's reactance", ["increases", "decreases", "stays the same", "falls to zero"], "Inductors oppose change; faster change = more opposition. This is why chokes block RF but pass DC.", "Inductor: Increases.");
Q("2E5", "The reactance of an inductor is given by", ["Vrms ÷ Irms ohms", "Irms ÷ Vrms ohms", "Vpeak ÷ Ipeak henries", "Ipeak ÷ Vpeak henries"], "Reactance is a V/I ratio in ohms, like resistance.");
Q("2E6", "'Impedance' describes", ["the overall ratio of voltage to current in an AC circuit", "resistance measured with a meter", "the current from a battery", "field strength"], "Impedance combines resistance and reactance, measured in ohms.");
Q("2E7", "The wavelength of a 7 MHz signal is about", ["43 m", "21 m", "70 m", "4.3 m"], "λ = 300 ÷ f(MHz) = 300 ÷ 7 ≈ 43 m.", "300 divided by MHz gives metres.");
Q("2E7", "A half-wave dipole 10 m long is designed for roughly", ["14 MHz", "7 MHz", "29 MHz", "3.5 MHz"], "Half-wave = 10 m, so wavelength = 20 m, so f = 300 ÷ 20 = 15 MHz. Nearest band: 14 MHz.");
Q("2E7", "432.675 MHz is in the", ["70 cm band", "2 m band", "23 cm band", "6 m band"], "300 ÷ 432 ≈ 0.69 m ≈ 70 cm.");
Q("2E8", "On a matched feeder carrying a 10 m wavelength, the voltage is at a peak. 2.5 m further along at the same instant it is", ["zero", "the positive peak", "the negative peak", "varying"], "2.5 m is a quarter wavelength = 90°. A quarter cycle on from a peak is a zero crossing.");
Q("2F1", "A digitised signal is represented more accurately by", ["more bits and a higher sampling rate", "fewer bits", "a lower sampling rate", "removing the anti-alias filter"], "More bits = finer amplitude steps. Higher sampling = finer time steps. Sampling error is a form of distortion.");
Q("2F1", "To capture a signal fully, it must be sampled at more than", ["twice its highest frequency", "its highest frequency", "half its highest frequency", "ten times its highest frequency"], "Twice the highest frequency is the Nyquist rate. RSGB questions may call this the minimum sampling rate.", "Nyquist: twice as quick.");
Q("2F1", "The minimum sampling rate needed to capture a signal is called the", ["Nyquist rate", "Fourier rate", "digital rate", "bit rate"], "Named after Harry Nyquist. Fourier is the transform that turns time into frequency.");
Q("2G1", "A transformer has 1000 primary turns and 50 secondary turns. With 230 V in, the output is", ["11.5 V", "4600 V", "23 V", "115 V"], "Voltage ratio = turns ratio: 230 × 50 ÷ 1000 = 11.5 V. Fewer secondary turns = step down.");
Q("2G1", "A transformer will NOT work with", ["steady DC", "50 Hz AC", "RF", "audio"], "It needs a changing magnetic field. Steady DC gives none, so nothing is induced.");
Q("2G1", "The iron core in a mains transformer", ["concentrates the magnetic field", "provides capacitance", "reduces the magnetic field", "adds stability"], "Iron (and ferrite at RF) links the field between the coils efficiently.");
Q("2H1", "A tuned circuit consists of", ["an inductor and a capacitor", "a resistor and an inductor", "a resistor and a capacitor", "a transistor and a resistor"], "LC = tuned. At resonance, XL = XC.");
Q("2H2", "At resonance, a series tuned circuit has", ["minimum impedance", "maximum impedance", "infinite impedance", "zero current"], "Series: reactances cancel → low impedance, max current. Parallel: high impedance.", "Series = Small. Parallel = Peak.");
Q("2H2", "At resonance, a parallel tuned circuit has", ["maximum impedance", "minimum impedance", "zero impedance", "no current circulating"], "This is why a parallel tuned circuit is used as a trap: it blocks its resonant frequency.");
Q("2H3", "If the capacitor in a tuned circuit is increased, the resonant frequency", ["falls", "rises", "stays the same", "doubles"], "More L or more C = lower frequency. Think: bigger, heavier, slower.");
Q("2H3", "Energy readily swaps between a capacitor and inductor at their", ["resonant frequency", "maximum usable frequency", "rejection frequency", "cut-off frequency"], "At resonance energy sloshes back and forth between the electric field (C) and magnetic field (L).");
Q("2H4", "A tuned circuit with a higher Q will have", ["a narrower bandwidth and better selectivity", "a wider bandwidth", "more loss", "a lower resonant frequency"], "High Q = sharp, narrow peak = more selective.");
Q("2H5", "A filter that passes frequencies below a cut-off and rejects those above is a", ["low-pass filter", "high-pass filter", "band-pass filter", "notch filter"], "It's named after what it lets through.");
Q("2H5", "A filter that rejects one narrow band of frequencies is a", ["band-stop (notch) filter", "band-pass filter", "low-pass filter", "high-pass filter"], "Notch = cuts a slot out of the response.");
Q("2I1", "Which component converts AC into DC?", ["Diode", "Transformer", "Inductor", "Polarised capacitor"], "A diode conducts one way only: rectification.");
Q("2I1", "Before a silicon diode conducts, the forward voltage must overcome the", ["depletion layer", "dielectric", "magnetic field", "reverse current"], "About 0.6 V for silicon is needed to overcome the depletion layer.");
Q("2I2", "The capacitance of a varicap diode depends on the", ["reverse bias voltage", "forward current", "frequency", "reverse current"], "Reverse-biased, the depletion layer acts as the dielectric. More reverse voltage = wider layer = less capacitance.");
Q("2I3", "Transistor current gain β is", ["Ic ÷ Ib", "Ib ÷ Ic", "Ie ÷ Ic", "Ic ÷ Ie"], "A small base current controls a bigger collector current. β = collector ÷ base.", "β = Big ÷ Base.");
Q("2I3", "A transistor with β = 100 has a base current of 20 µA. The collector current is", ["2 mA", "200 µA", "20 mA", "0.2 mA"], "Ic = β × Ib = 100 × 20 µA = 2000 µA = 2 mA.");
Q("2I4", "Providing a transistor with the right DC voltages and currents to operate is called", ["biasing", "switching", "amplifying", "field effecting"], "Biasing sets the 'resting' operating point so the signal can swing either way.");
Q("2I4", "In a common emitter amplifier on 12 V, Ic is 2 mA. For the collector to sit at 6 V, the collector resistor is", ["3 kΩ", "6 kΩ", "1.5 kΩ", "12 kΩ"], "Half the supply (6 V) is dropped across Rc. R = 6 ÷ 0.002 = 3000 Ω.");
Q("2I5", "A transistor used to generate audio or RF is working as", ["an oscillator", "a detector", "a filter", "a mixer"], "Oscillators sustain oscillation in a tuned (frequency-selective) circuit. The syllabus example is the Colpitts.");
Q("2I6", "An integrated circuit is best described as", ["many devices built on one substrate in one package", "a surface-mount resistor", "a single transistor", "a ceramic capacitor"], "ICs can be amplifiers, oscillators, regulators or digital processors.");
Q("2J1", "A battery rated in ampere-hours (Ah) tells you", ["how much charge it stores, an indication of its capacity", "its maximum charge current", "how long before it needs recharging", "its terminal voltage"], "A 7 Ah battery can supply 1 A for about 7 hours, or 7 A for about 1 hour.");
Q("2J2", "For the same smoothing, which rectifier needs the largest reservoir capacitor?", ["Half-wave", "Full-wave", "Bridge", "They are all the same"], "Half-wave only charges the capacitor once per cycle (50 Hz), so it must hold up longer than full-wave or bridge (100 Hz).");
Q("2J3", "In a mains power supply, smoothing is provided by the", ["reservoir capacitor", "fuse", "rectifier", "transformer"], "The capacitor charges on the peaks and discharges between them, filling in the gaps.");
Q("2J4", "Compared with a linear supply, a switched-mode supply is", ["smaller, lighter and more efficient, but can cause more RF interference", "heavier and less efficient", "free of RF interference", "always larger"], "Switch-mode runs at high frequency with a small ferrite transformer. The switching can radiate RF noise.");
Q("2J4", "A feature of an IC linear power supply is that", ["most regulation is done inside one integrated circuit", "it switches at 20 kHz or more", "it uses a ferrite transformer", "regulation uses many separate transistors"], "Regulator ICs such as the 78xx family contain the whole control circuit.");

/* ───────────── SECTION 3 · TRANSMITTERS & RECEIVERS ───────────── */
Q("3A2", "Peak deviation in an FM transmission is the", ["maximum shift from centre frequency at the peaks of the modulating signal", "maximum shift at the highest audio frequency", "carrier ÷ audio frequency", "audio ÷ carrier frequency"], "Deviation follows the audio's loudness (amplitude), not its pitch.");
Q("3A3", "SSB is more efficient than AM because", ["no power is wasted in the carrier or the second sideband", "it uses a higher frequency", "it has a wider bandwidth", "it needs no filters"], "All the power goes into the one sideband that carries the information. It also uses half the bandwidth.");
Q("3A3", "In order of increasing bandwidth:", ["CW, SSB, AM, FM", "SSB, CW, FM, AM", "FM, AM, SSB, CW", "AM, SSB, CW, FM"], "CW is narrowest; FM widest. Typical: CW ~100 Hz, SSB ~3 kHz, AM ~6 kHz, FM ~12 kHz.", "Can Simple Amateurs Fit? (CW SSB AM FM)");
Q("3A3", "An SSB signal occupies about how much bandwidth compared with AM?", ["Half", "Double", "The same", "A quarter"], "AM has two sidebands (~6 kHz). SSB keeps one (~3 kHz).");
Q("3B1", "In a simple CW transmitter, the stage after the oscillator that boosts the signal to the antenna is the", ["power amplifier", "modulator", "AF amplifier", "sideband filter"], "CW: oscillator → (buffer) → power amplifier, with keying.");
Q("3C1", "The main advantage of a VFO over a crystal oscillator is", ["the frequency can be changed", "it is more stable", "its frequency is preset", "it cannot be pulled"], "Crystal = stable but fixed. VFO = tunable but less stable.");
Q("3C2", "Oscillator stability is improved by", ["rigid construction, screening, a regulated supply and a buffer stage", "a higher supply voltage", "using larger-value capacitors only", "removing the buffer"], "Any physical, thermal or electrical disturbance can make the frequency drift, possibly out of band.");
Q("3C3", "Direct Digital Synthesis (DDS) generates a signal from", ["digital values stored in a lookup table", "a tuned LC circuit", "a quartz crystal alone", "a varicap diode"], "Numbers are fed to a DAC to build the waveform point by point.");
Q("3E1", "The output of a balanced modulator contains", ["two sidebands with the carrier suppressed", "the carrier and both sidebands", "one sideband only", "the carrier only"], "It balances out the carrier. A filter then removes one sideband to leave SSB.");
Q("3E2", "Sideband filters are", ["band-pass filters", "band-stop filters", "high-pass filters", "low-pass filters"], "They pass just the wanted sideband, typically using quartz crystals.");
Q("3E3", "FM can be generated by", ["applying audio to a varicap diode in an oscillator", "mixing audio and RF in a balanced modulator", "varying the PA supply voltage", "keying the oscillator"], "The audio changes the varicap's capacitance, which shifts the oscillator frequency.");
Q("3F1", "A PA draws 100 W of DC power and is 60% efficient. The RF output is about", ["60 W", "40 W", "100 W", "160 W"], "RF out = DC in × efficiency. The other 40 W becomes heat.");
Q("3G2", "Harmonics are", ["multiples of the fundamental frequency", "multiple ionospheric reflections", "natural interference", "random mixing products"], "A 7 MHz transmitter can produce harmonics at 14, 21, 28 MHz… which can land in other bands or services.");
Q("3G3", "Harmonics from a transmitter are best reduced by fitting a", ["low-pass filter at the transmitter output", "high-pass filter at the transmitter", "notch filter on the mains", "longer feeder"], "Harmonics are higher than the wanted signal, so a low-pass filter lets the fundamental through and blocks them.");
Q("3G4", "Key clicks are caused by", ["keying with too fast a rise and fall time", "keying too slowly", "a weak power supply", "over-deviation"], "Sharp edges create wide sidebands. Shaping the keying slows the edges and narrows the signal.");
Q("3G4", "The CW waveform giving the narrowest bandwidth has", ["gently sloped rise and fall", "vertical edges", "overshoot on each element", "a square shape"], "Rounded edges = fewer high-frequency components = narrower signal.");
Q("3G5", "'Chirp' on a CW signal is", ["a frequency shift when keying, caused by oscillator instability", "too fast keying", "over-modulation", "harmonic radiation"], "The note 'slides' as the key goes down, often from the supply voltage dropping. Cure: stable supply, buffer, key a later stage.");
Q("3H2", "In an analogue receiver, the detector comes", ["after the RF amplifier and before the audio amplifier", "before the RF amplifier", "after the audio amplifier", "before the antenna"], "Antenna → RF amp → detector → audio amp → speaker.");
Q("3H3", "Tuning to a very strong signal may", ["overload the receiver and distort the audio", "damage the AGC", "mute the speaker", "make the oscillator drift"], "Sensitivity is about weak signals; a very strong one can overload the stages.");
Q("3H4", "If a receiver's tuned circuits have low Q", ["adjacent signals are more likely to interfere", "adjacent signals are less likely to interfere", "background noise is greatly reduced", "it becomes more selective"], "Low Q = broad tuning = poor selectivity.");
Q("3I1", "Above about 3 MHz a crystal set gives way to a superhet mainly because the crystal set lacks", ["selectivity", "an aerial", "automatic gain control", "a speaker"], "Simple tuned circuits aren't selective enough at HF. The superhet's fixed IF gives good selectivity.");
Q("3I2", "The intermediate frequency in a superhet can be the", ["difference between the RF and local oscillator frequencies", "sum of RF and audio", "difference of audio and local oscillator", "sum of audio and local oscillator"], "The mixer produces sum and difference frequencies; one is chosen as the IF.");
Q("3I2", "Signal 14.2 MHz, IF 9 MHz. A suitable local oscillator is", ["5.2 MHz", "14.2 MHz", "9 MHz", "23.2 MHz only"], "14.2 − 9 = 5.2 MHz. (23.2 MHz would also work; 'only' makes that option wrong.)");
Q("3I3", "In a superhet, the RF amplifier", ["selects a range of signals including the wanted one", "selects only the wanted signal", "converts to the IF", "selects the mode"], "The RF stage is broadly tuned. Sharp selectivity is done later at the IF.");
Q("3K1", "To demodulate CW a receiver needs a", ["beat frequency oscillator (BFO)", "discriminator", "diode detector only", "narrow notch filter"], "The BFO beats with the carrier to produce an audible tone.");
Q("3K1", "A receiver's IF is 455 kHz. A CW signal will give a 1 kHz tone if the BFO is on", ["454 kHz", "455 kHz", "10 MHz", "1 kHz"], "BFO is set about 1 kHz away from the IF: 454 or 456 kHz.");
Q("3K1", "SSB is demodulated using", ["a product detector and carrier insertion oscillator", "a discriminator", "a diode detector", "a ratio detector"], "SSB has no carrier, so one is re-inserted (CIO) and mixed in a product detector.");
Q("3K1", "FM is demodulated using a", ["discriminator", "BFO", "diode detector", "product detector"], "A discriminator turns frequency changes back into voltage changes (audio).");
Q("3L1", "A receiver's S-meter usually reads a signal derived from the", ["AGC voltage", "audio level", "RF amplifier", "first mixer bias"], "AGC measures signal strength at the detector and adjusts gain. The same voltage drives the S-meter.");
Q("3M1", "An SDR produces its spectrum display using", ["a Fourier transform", "sampling the audio while tuning", "variable tuned circuits", "mixing with the original RF"], "The FFT breaks the sampled signal into its frequency components. That gives the spectrum and waterfall.");
Q("3M2", "A sine wave with a single third harmonic appears in the frequency domain as", ["two vertical lines, at f and 3f", "one line at 3f", "a continuous smear", "three equal lines"], "Each pure sine is one line in the frequency domain.");
Q("3M3", "In an SDR receiver, before the analogue-to-digital converter there is usually", ["a low-pass (anti-aliasing) filter", "a Fourier transform", "a loudspeaker", "a discriminator"], "Anything above half the sampling rate must be removed before sampling, otherwise it aliases.");
Q("3N1", "RIT on a transceiver lets you", ["shift the receive frequency without moving the transmit frequency", "change transmit power", "switch antennas", "record a QSO"], "Receiver Incremental Tuning: handy when the other station is slightly off frequency.");

/* ───────────── SECTION 4 · FEEDERS & ANTENNAS ───────────── */
Q("4A1", "A balanced (twin) feeder does not radiate because", ["equal and opposite currents produce fields that cancel", "the field stays between the conductors", "standing waves can't escape", "the insulation screens it"], "Keep it clear of metal objects, which can unbalance it and make it radiate.");
Q("4A1", "For a rectangular waveguide to work, its larger dimension must be greater than", ["half a wavelength", "a quarter wavelength", "one wavelength", "two wavelengths"], "That's why waveguides are only practical at microwave frequencies.");
Q("4A2", "One advantage of twin feeder over coax is", ["lower loss", "built-in screening", "an earth connection", "50 Ω impedance"], "Open-wire / ladder line has very low loss, but must be kept clear of objects.");
Q("4A2", "A transmitter gives 100 W into a feeder with 3 dB loss. Power at the antenna is", ["50 W", "97 W", "25 W", "33 W"], "−3 dB = half power.");
Q("4A2", "40 W reaches the antenna through a feeder with 10 dB loss. The transmitter output is", ["400 W", "4 W", "50 W", "100 W"], "10 dB = ×10. Working backwards, the transmitter must give 10 × 40 W.");
Q("4A3", "Amateur coaxial cable is normally", ["50 Ω", "75 Ω", "300 Ω", "600 Ω"], "TV/satellite coax is 75 Ω. Balanced feeder ranges from 75 Ω to 600 Ω.");
Q("4A3", "A feeder's characteristic impedance depends on", ["the diameter and spacing of the conductors", "its length", "the frequency", "the transmitter power"], "Not length! A correctly terminated feeder looks like its characteristic impedance whatever its length.");
Q("4B1", "A choke balun on a coax feed to a Yagi mainly", ["stops RF currents flowing on the outside of the braid", "matches impedance for low SWR", "reduces current on the inner conductor", "increases the gain"], "It stops the feeder becoming part of the antenna (common-mode current), which upsets the pattern and causes EMC problems.");
Q("4C2", "The beamwidth of a Yagi is the", ["angle between the half-power points", "length of the reflector", "spacing of the elements", "boom length"], "Half power = −3 dB points either side of the main lobe.");
Q("4C2", "Front-to-back ratio compares", ["signal in the forward direction with signal off the back", "the driven element and the reflector", "forward and reflected power", "horizontal and vertical radiation"], "Expressed in dB. A good beam rejects signals from behind.");
Q("4C3", "An isotropic radiator is", ["a theoretical point source radiating equally in all directions", "a real dipole", "2.15 dB better than a dipole", "a vertical antenna"], "It's the reference for dBi. A half-wave dipole has 2.15 dBi gain.");
Q("4C3", "A half-wave dipole has a gain over an isotropic radiator of", ["2.15 dB", "0 dB", "3 dB", "6 dB"], "So EIRP = ERP + 2.15 dB.");
Q("4C4", "To improve long-distance HF contacts you should reduce the", ["angle of radiation", "antenna height", "feed impedance", "number of elements"], "Long distance needs low-angle radiation. Raising the antenna usually lowers the angle.");
Q("4C5", "A centre-fed half-wave dipole in practice, near ground, has a feed impedance of roughly", ["50 Ω", "300 Ω", "600 Ω", "10 Ω"], "Theory (free space) says 73 Ω; in practice it's around 50 Ω, a good match for coax.");
Q("4D1", "In a three-element Yagi, the reflector is", ["slightly longer than the driven element", "slightly shorter", "the same length", "connected to the feeder"], "Reflector longer, director shorter. The feeder goes to the driven element.", "Reflector = Roomier. Director = Diminutive.");
Q("4D1", "The feeder of a Yagi connects to the", ["driven element", "director", "reflector", "boom"], "Only the driven element is fed; the others are 'parasitic'.");
Q("4D2", "An antenna trap is a", ["parallel tuned circuit", "series tuned circuit", "resistor", "balun"], "At its resonant frequency it has high impedance and 'cuts off' the rest of the element.");
Q("4D2", "A dipole with four traps (two each side) works on about", ["three bands", "four bands", "five bands", "two bands"], "One band with both traps active, one with the outer traps, one using the full length: traps per side + 1.");
Q("4E1", "Standing waves on a feeder are caused by", ["forward RF combining with RF reflected from the antenna", "RF radiated by the antenna", "current on the braid", "RF leaving the feeder"], "A mismatch reflects power back; forward and reflected waves add and cancel along the line.");
Q("4F1", "An ATU at the transmitter, correctly adjusted", ["has no effect on SWR between the ATU and the antenna", "reduces the SWR on the feeder", "reduces feeder loss", "changes the polarisation"], "It only makes the transmitter see the right load. The feeder and antenna mismatch is untouched.", "ATU fools the rig, not the feeder.");
Q("4H1", "The main reason for using PL259/SO239 connectors on a coax feed is to", ["keep the RF contained within the connection", "stop accidental disconnection", "convert 75 Ω to 50 Ω", "avoid soldering"], "A proper coax connector keeps the screen continuous so RF stays inside.");

/* ───────────── SECTION 5 · PROPAGATION ───────────── */
Q("5A2", "A 28 MHz signal heard 5 km away is most likely travelling by", ["ground wave", "sky wave", "skip", "the ionosphere"], "Short distances are covered by ground wave before the sky wave returns.");
Q("5A2", "The 'skip zone' is", ["the area between the end of ground wave and the first sky wave return", "the area beyond the horizon", "a region of the ionosphere", "the distance of one hop"], "No signal is heard there: too far for ground wave, too near for the sky wave.");
Q("5A3", "The factor with most effect on ground wave range is", ["frequency", "time of day", "sunspot cycle", "ducting"], "Ground absorption increases with frequency, so ground wave works best at LF/MF.");
Q("5A4", "An EM wave travels", ["at right angles to both the electric and magnetic fields", "parallel to the electric field", "parallel to the magnetic field", "at right angles to the electric field only"], "E-field, H-field and direction of travel are all at 90° to each other.");
Q("5A4", "Polarisation of a radio wave is defined by the plane of its", ["electric field", "magnetic field", "direction of travel", "antenna feeder"], "A vertical dipole produces vertical polarisation (E-field vertical).");
Q("5B1", "The ionosphere's layers are ionised by", ["solar radiation", "lightning", "high pressure", "the Earth's rotation"], "UV and charged particles from the sun. The layers are D (lowest), E, F1, F2 (highest).");
Q("5B2", "HF propagation is strongly affected by the", ["sunspot cycle", "barometric pressure", "height of mountains", "humidity"], "The roughly 11-year cycle: more sunspots generally mean better HF conditions, especially on the higher bands.");
Q("5B2", "The MUF is", ["the highest frequency refracted back over a given path", "the lowest usable frequency", "the frequency of the strongest signal", "the frequency of sporadic E"], "Maximum Usable Frequency. Above it, signals go straight through the ionosphere.");
Q("5B3", "A single hop off the F2 layer reaches about", ["4000 km", "2000 km", "8000 km", "16000 km"], "E layer about 2000 km; F2 about 4000 km. Multiple hops reach worldwide.", "E = 2k, F = 4k.");
Q("5B4", "The D layer", ["absorbs lower HF signals during the day", "reflects HF signals at night", "has no effect on HF", "is the highest layer"], "It forms in daylight and largely disappears at night, which is why 80 m and 160 m open up after dark.");
Q("5B4", "If the LUF is higher than the MUF", ["no ionospheric propagation is possible on that path", "propagation is excellent", "only ground wave works on HF", "sporadic E occurs"], "The usable window has closed: anything low is absorbed, anything high goes through.");
Q("5B5", "The greatest distance by a single E-layer hop is about", ["2000 km", "5000 km", "10000 km", "500 km"], "Sporadic E also boosts 28 MHz and VHF in summer.");
Q("5C3", "Multipath at VHF/UHF happens when", ["signals reflect off buildings or aircraft in addition to the direct path", "two stations transmit together", "ground and sky waves arrive together", "there is no direct path"], "The reflected copies arrive slightly later, causing fading or 'picket fencing'.");

/* ───────────── SECTION 6 · EMC ───────────── */
Q("6A1", "Which can radiate and absorb RF energy?", ["All electronic equipment", "Only amateur transceivers", "Only TV sets", "Only broadcast receivers"], "EMC is about all equipment working together in its environment.");
Q("6A2", "A device's immunity can be improved by", ["filtering power, signal and control leads", "the amateur using lower power", "transmitting on a lower frequency", "screening the transmitter"], "Immunity is a property of the victim device. Screening and filtering its leads helps.");
Q("6A4", "New equipment meeting EMC standards is most likely to suffer interference if", ["it has been poorly installed", "it is used at home", "it lacks commercial filters", "it is badly designed"], "A compliant device can still suffer if installation (long leads, poor connections) undermines it.");
Q("6B1", "Which mode most often causes speech-like sounds on audio equipment and phones?", ["SSB", "FM", "CW", "PSK"], "AM and SSB are rectified into audio. FM tends to cause muting or reduced signal instead.");
Q("6B2", "Interference from a vacuum cleaner on an amateur receiver sounds like", ["a rough continuous noise", "50 Hz hum", "a low musical tone", "a high whistle"], "Brushed motors spark, giving broadband buzzing that tracks the motor.");
Q("6B3", "Interference to digital TV usually shows as", ["freezing, blocky pixelation or loss of picture", "patterning lines only", "speech in the sound", "a change of channel"], "Digital systems tend to fail abruptly. DAB radio typically mutes.");
Q("6C2", "Your 435 MHz signal interferes with a TV that has a masthead amplifier. Most likely", ["the masthead amplifier is amplifying your signal and overloading", "a harmonic is in the TV band", "the TV picks it up directly", "it's entering via the mains"], "Broadband masthead amplifiers amplify everything, including nearby amateur signals.");
Q("6D1", "HF interference to a UHF TV can often be cured by fitting a", ["high-pass filter at the TV aerial socket", "low-pass filter at the TV socket", "high-pass filter at the transmitter", "low-pass filter on the TV aerial"], "The TV wants UHF (high); your HF signal is low. A high-pass filter lets UHF through and blocks HF.", "Filter at the victim; pass what the victim needs.");
Q("6D2", "A ferrite choke on a feeder attenuates", ["common-mode currents", "differential-mode currents", "DC", "balanced currents"], "Common mode = same direction on both conductors / outside of braid. The ferrite chokes these while leaving the wanted signal alone.");
Q("6D3", "Which could NOT be used to look for harmonics from a 3.5 MHz transmitter?", ["A digital frequency meter", "A spectrum analyser", "A general coverage receiver", "An SDR dongle"], "A frequency counter shows one frequency (the strongest); it can't show separate harmonics.");
Q("6D4", "A dummy load used for testing must be", ["non-reactive and of suitable power rating", "wire-wound", "reactive", "connected to the mains earth"], "It lets you transmit without radiating, to check whether interference is radiated or conducted.");
Q("6E1", "The best cable between microphone and transmitter is", ["screened cable", "twisted twin flex", "50 Ω coax", "twin and earth"], "Screening keeps RF out of the mic lead.");
Q("6E2", "A good RF earth is a connection to", ["an earth stake close to the station", "the mains earth", "the water pipe", "the gas pipe"], "Short, thick connection to dedicated rods. Never gas or water pipes.");
Q("6E3", "The most serious problem with an indoor antenna near mains wiring is", ["RF getting into the mains wiring", "mains noise on receive", "fuses failing", "equipment becoming live"], "Loft and indoor antennas couple strongly into house wiring and cause EMC problems.");
Q("6F3", "On a car, which mobile antenna position usually gives the lowest RF field inside the vehicle?", ["Centre of the roof", "Boot lid", "Wing", "Inside the windscreen"], "The metal roof screens the occupants. Wing and boot mounts give higher exposure.");

/* ───────────── SECTION 7 · OPERATING ───────────── */
Q("7A3", "Which is a prefix for the USA?", ["W", "VE", "I", "VK"], "W (also K, N, AA–AL). VE is Canada, VK Australia, I Italy.");
Q("7A3", "The prefix VK belongs to", ["Australia", "Canada", "New Zealand", "Japan"], "VK Australia, ZL New Zealand, JA Japan, VE Canada.", "VK: Very Kangaroo.");
Q("7A3", "PA is the prefix for", ["the Netherlands", "Portugal", "Panama", "Poland"], "Also EI Ireland, F France.");
Q("7A4", "Contests generally require", ["correct exchange of specified information", "RSGB membership", "QSL cards for all contacts", "operation from remote sites"], "Typically report plus serial number or locator.");
Q("7B1", "Amateur band plans are produced by the", ["IARU", "ITU", "Ofcom", "RSGB exams team"], "The International Amateur Radio Union Region 1 plan. The RSGB publishes the UK version.");
Q("7B1", "Which band has no SSB and no contests?", ["10 MHz (30 m)", "14 MHz (20 m)", "7 MHz (40 m)", "21 MHz (15 m)"], "30 m is narrow and secondary: CW and data only. No contests on 30, 17, 12 or 60 m.");
Q("7B1", "Below 10 MHz voice SSB normally uses", ["lower sideband", "upper sideband", "either sideband", "double sideband"], "LSB below 10 MHz, USB above (60 m is the exception, using USB). It's printed in the EX308 band plan notes.");
Q("7B1", "The 2 m FM calling channel is", ["145.500 MHz", "144.300 MHz", "145.800 MHz", "144.800 MHz"], "144.300 is the SSB centre, 144.800 APRS, 145.800 is the ISS downlink. Check EX308.");
Q("7E1", "QRT means", ["stop transmitting", "change frequency", "increase power", "where are you?"], "QSY change frequency, QRO increase power, QTH location.");
Q("7E1", "QSB means", ["fading", "interference", "noise", "confirmation"], "QRM man-made interference, QRN natural noise, QSL confirm.");
Q("7E1", "QRP means", ["low power", "high power", "stop sending", "location"], "QRP low power, QRO increase power.");
Q("7F2", "A computer sound card can be used to", ["send and receive data modes via amateur radio", "adjust HF receive filters", "only receive signals", "control transmit frequency"], "Set the audio level carefully into the transmitter to avoid distortion and splatter. Turn off system beeps!");
Q("7G1", "Most amateur satellites", ["orbit the Earth and are only in view at certain times", "stay above one point", "are always in view", "orbit below 100 km"], "They're in low orbits (above 250 km). You track passes.");
Q("7G2", "Satellite uplink and downlink are usually", ["in different amateur bands", "on the same frequency", "both in the HF bands", "on the FM calling channel"], "E.g. uplink 2 m, downlink 70 cm. You should be able to hear your own downlink.");
Q("7G3", "When working a satellite you must allow for", ["Doppler shift", "sporadic E", "the skip zone", "LUF"], "The satellite's speed shifts the frequency during the pass.");
Q("7G4", "Using excessive uplink power on a satellite is", ["wasteful of its limited solar power and unfair on others", "required for a good signal", "always permitted", "needed to overcome Doppler"], "Use only enough power to hear your own downlink comfortably.");

/* ───────────── SECTION 8 · SAFETY ───────────── */
Q("8A1", "A high-value resistor across a high-voltage capacitor is there to", ["discharge it after switch-off to prevent shock", "dampen oscillation", "limit supply current", "increase current capacity"], "A 'bleed' resistor. Still check the capacitor is discharged before touching.");
Q("8A4", "A 13 A plug's fuse should be", ["replaced with one rated just above what the equipment draws", "left at 13 A always", "bypassed with foil", "replaced with a higher rating"], "Current = power ÷ 230 V. A 460 W device draws 2 A → a 3 A fuse.");
Q("8A4", "A 690 W appliance on 230 V mains draws", ["3 A", "30 A", "0.3 A", "6.9 A"], "I = P ÷ V = 690 ÷ 230 = 3 A. Use the next fuse up (5 A).");
Q("8A6", "The main reason to avoid working on powered equipment is to", ["reduce the risk of electric shock", "avoid unwanted transmission", "avoid damaging the equipment", "make adjustment easier"], "Only work live if there's no alternative and you fully understand the risks.");
Q("8A8", "When charging a car battery you must ensure", ["good ventilation, because hydrogen is given off", "it is in a sealed box", "it is fully discharged first", "it is earthed to the mains"], "Hydrogen is explosive. Car batteries can also deliver huge currents and contain corrosive acid.");
Q("8B2", "The most serious result of careless screwdriver use is", ["injury", "a damaged screw slot", "a broken screwdriver", "a scratched panel"], "Always the injury answer. Keep fingers behind the blade.");
Q("8B3", "When drilling, it's most important to", ["securely clamp the item being drilled", "hold it with one hand", "rest it on a flat surface", "keep a hand in your pocket"], "Use a vice or clamp. A drill can grab and spin unsecured work.");
Q("8B4", "Before starting an electric drill, check that", ["the chuck key has been removed", "your goggles are off", "the work is earthed", "you're using an undersized bit"], "A chuck key left in gets flung out at speed.");
Q("8B5", "A centre punch is used before drilling to", ["stop the drill bit wandering", "measure the hole", "remove burrs", "earth the work"], "A small dimpled start mark guides the bit.");
Q("8D1", "When transmitting from a stationary vehicle, you must consider", ["whether people nearby are within the EMF compliance distance", "your location to within 5 km", "passengers' voices being heard", "interference from the ignition"], "In traffic or parked, pedestrians may be close to the antenna.");

/* ───────────── SECTION 9 · MEASUREMENT & CONSTRUCTION ───────────── */
Q("9A1", "To measure resistance with a multimeter, set the switch to", ["ohms", "DC volts", "AC volts", "current"], "And always set the range before connecting.");
Q("9A2", "To measure voltage, a multimeter is connected", ["in parallel across the component", "in series with the component", "in series with the component removed", "across the supply only"], "Voltmeters: parallel, high resistance. Ammeters: series, low resistance.", "Volts across, amps along.");
Q("9A2", "An ammeter has", ["low internal resistance and goes in series", "high internal resistance and goes in series", "low resistance and goes in parallel", "high resistance and goes in parallel"], "Low resistance so it doesn't disturb the current it's measuring.");
Q("9A3", "When tuning for a peak reading, the best meter is", ["an analogue meter", "a digital meter", "a frequency counter", "an absorption wavemeter"], "A moving needle shows trends and peaks; digits flicker.");
Q("9A5", "A voltmeter reads 12 V and an ammeter 2.5 A. Power is", ["30 W", "4.8 W", "14.5 W", "9.5 W"], "P = V × I = 12 × 2.5 = 30 W.");
Q("9B1", "A gain of 6 dB is a power ratio of", ["4×", "2×", "6×", "8×"], "3 dB = 2×. 6 dB = 2 × 2 = 4×.", "Every 3 dB doubles, every 10 dB ×10.");
Q("9B1", "800 W expressed in dBW is", ["29 dBW", "27 dBW", "30 dBW", "80 dBW"], "100 W = 20 dBW. 800 W is 8× (= +9 dB): 29 dBW.");
Q("9B1", "The gain of an antenna is expressed in", ["dB", "volts per metre", "amps per metre", "MHz"], "dBi relative to isotropic, dBd relative to a dipole.");
Q("9B1", "25 W expressed in dBW is", ["14 dBW", "25 dBW", "4 dBW", "40 dBW"], "10 W = 10 dBW, 20 W = 13, 25 W ≈ 14 dBW (the syllabus example).");
Q("9C1", "A resistor coded yellow, violet, orange is", ["47 kΩ", "473 Ω", "4.7 kΩ", "470 kΩ"], "4, 7, then ×1000 = 47,000 Ω. The colour code is in EX308.");
Q("9C1", "'4R7' marked on a resistor means", ["4.7 Ω", "47 Ω", "4.7 kΩ", "470 Ω"], "R marks the decimal point. 3k3 = 3.3 kΩ.");
Q("9C1", "A capacitor marked 103 is", ["10 nF", "103 pF", "10 µF", "1 nF"], "10 followed by 3 zeros, in pF = 10,000 pF = 10 nF.");
Q("9D1", "Thin metal sheet is used inside equipment to", ["screen stages and reduce unwanted radiation", "add strength", "act as a heatsink only", "earth the mains"], "Screening between stages prevents unwanted coupling and radiation.");
Q("9E1", "Soldering is", ["melting a low-melting-point alloy to flow around the joint", "melting the copper wires together", "gluing with flux", "pressing wires together with heat"], "The parts themselves don't melt; the solder bonds them.");
Q("9E2", "Flux in solder", ["prevents oxidation and helps the solder flow", "is corrosive and should be avoided", "makes the joint mechanically stronger", "cools the joint"], "Clean surfaces + flux = a good bright joint.");
Q("9E4", "Tinning the soldering iron tip", ["prevents oxidation and improves heat transfer", "cools the iron", "earths the iron", "is only needed with lead-free solder"], "Clean the tip, then coat with a little solder.");
